CSV_OUT = OUT_DIR / "step14_calibration_axes.csv"
JSON_OUT = OUT_DIR / "step14_calibration_axes.json"
PLOTS_OUT_DIR = OUT_DIR / "step14_calibration_plots"
PLOTS_OUT_DIR.mkdir(parents=True, exist_ok=True)

SHOW_PLOTS = True
N_BINS = 15
CALIB_FALLBACK_FRAC = 0.2  # used only if calib files don't exist

AXIS_SPECS: Dict[str, Dict[str, Any]] = {
    "axis1": {"title": "Axis 1: Progression", "classes": ["RP", "SP"]},
    "axis2": {"title": "Axis 2: Subtype", "classes": ["MET", "INF", "HYP", "MIX"]},
    "axis3": {"title": "Axis 3: Mismatch", "classes": ["Hyper", "Coupled", "Silent"]},
}

COVARIATE_COLS = ["sex", "ethnicity"]

NUM_COLS_13 = [
    "age_years",
    "diabetes_duration_years",
    "dpn_duration_years",
    "pain_score_0_10",
    "TNF_alpha_pg_ml",
    "IL6_pg_ml",
    "MDA_umol_L",
    "EMG_MUNE",
    "EMG_MUI",
    "EMG_MUAP_I",
    "EMG_RMS_mean",
    "EMG_median_frequency",
    "EMG_fasciculation_rate",
]


# -----------------------
# Utils
# -----------------------
def _atomic_write_json(path: Path, obj: Any) -> None:
    tmp = path.with_suffix(path.suffix + ".tmp")
    with tmp.open("w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=2)
    os.replace(tmp, path)


def _ensure_cols(df: pd.DataFrame, cols: List[str], default: Any) -> pd.DataFrame:
    out = df.copy()
    for c in cols:
        if c not in out.columns:
            out[c] = default
    return out


def _to_num(df: pd.DataFrame, cols: List[str]) -> pd.DataFrame:
    out = df.copy()
    for c in cols:
        out[c] = (
            pd.to_numeric(out[c], errors="coerce")
            .replace([np.inf, -np.inf], np.nan)
            .fillna(0.0)
            .astype(np.float32)
        )
    return out


def _to_int(df: pd.DataFrame, cols: List[str]) -> pd.DataFrame:
    out = df.copy()
    for c in cols:
        out[c] = (
            pd.to_numeric(out[c], errors="coerce")
            .replace([np.inf, -np.inf], np.nan)
            .fillna(0)
            .astype(np.int64)
        )
    return out


def _infer_pv_dim(sd: Dict[str, torch.Tensor]) -> int:
    k = "pv_decoder.net.2.weight"
    if k not in sd or not isinstance(sd[k], torch.Tensor) or sd[k].ndim != 2:
        raise RuntimeError("Cannot infer pv_dim from checkpoint: missing pv_decoder.net.2.weight")
    return int(sd[k].shape[0])


def _infer_cov_rows_from_ckpt(sd: Dict[str, torch.Tensor], n_cat: int) -> List[int]:
    rows: List[int] = []
    for i in range(n_cat):
        k = f"cov_emb.emb.{i}.weight"
        if k not in sd or not isinstance(sd[k], torch.Tensor) or sd[k].ndim != 2:
            raise RuntimeError(f"Cannot infer cov embedding rows from checkpoint: missing {k}")
        rows.append(int(sd[k].shape[0]))
    return rows


def _num_cat_list_for_model_init(cov_rows_ckpt: List[int]) -> List[int]:
    # HybridDPNModel internally expands category sizes by +1, so pass (rows-1) to match ckpt weights.
    out: List[int] = []
    for r in cov_rows_ckpt:
        v = int(r) - 1
        if v < 1:
            v = 1
        out.append(v)
    return out


def _clamp_cats_np(x_cat: np.ndarray, cov_rows: List[int]) -> np.ndarray:
    out = x_cat.astype(np.int64, copy=True)
    for j, rows in enumerate(cov_rows):
        max_orig = int(rows - 2)  # valid original idx: -1..rows-2 (because model does +1)
        if max_orig < -1:
            max_orig = -1
        out[:, j] = np.clip(out[:, j], -1, max_orig)
    return out


def _pick_logits(out_dict: Dict[str, torch.Tensor], axis_key: str) -> torch.Tensor:
    for k in (f"{axis_key}_logits", axis_key):
        if k in out_dict and isinstance(out_dict[k], torch.Tensor):
            return out_dict[k]
    raise KeyError(f"Missing logits for {axis_key}. Keys: {list(out_dict.keys())}")


def _nll(y_true: np.ndarray, proba: np.ndarray) -> float:
    y = y_true.astype(np.int64, copy=False)
    p = np.clip(proba.astype(np.float64, copy=False), 1e-12, 1.0)
    return float(-np.mean(np.log(p[np.arange(y.shape[0]), y])))


def _brier_multiclass(y_true: np.ndarray, proba: np.ndarray, n_classes: int) -> float:
    y = y_true.astype(np.int64, copy=False)
    oh = np.zeros((y.shape[0], n_classes), dtype=np.float32)
    oh[np.arange(y.shape[0]), y] = 1.0
    return float(np.mean(np.sum((proba.astype(np.float32, copy=False) - oh) ** 2, axis=1)))


def _reliability_bins(conf: np.ndarray, correct: np.ndarray, n_bins: int) -> Dict[str, Any]:
    edges = np.linspace(0.0, 1.0, n_bins + 1, dtype=np.float64)
    bin_acc = np.zeros(n_bins, dtype=np.float64)
    bin_conf = np.zeros(n_bins, dtype=np.float64)
    bin_count = np.zeros(n_bins, dtype=np.int64)

    for i in range(n_bins):
        lo, hi = edges[i], edges[i + 1]
        m = (conf >= lo) & (conf <= hi) if i == 0 else (conf > lo) & (conf <= hi)
        cnt = int(m.sum())
        bin_count[i] = cnt
        if cnt > 0:
            bin_acc[i] = float(np.mean(correct[m]))
            bin_conf[i] = float(np.mean(conf[m]))

    n = float(max(int(conf.shape[0]), 1))
    w = bin_count.astype(np.float64) / n
    gaps = np.abs(bin_acc - bin_conf)
    ece = float(np.sum(w * gaps))
    mce = float(np.max(gaps)) if gaps.size else float("nan")

    centers = (edges[:-1] + edges[1:]) / 2.0
    return {
        "edges": edges.tolist(),
        "centers": centers.tolist(),
        "bin_acc": bin_acc.tolist(),
        "bin_conf": bin_conf.tolist(),
        "bin_count": bin_count.tolist(),
        "ece": ece,
        "mce": mce,
    }


def _fit_temperature(logits: torch.Tensor, y: torch.Tensor) -> float:
    if logits.numel() == 0 or y.numel() == 0:
        return 1.0
    y = y.to(torch.long)
    if int(torch.unique(y).numel()) < 2:
        return 1.0

    log_T = torch.zeros((), device=logits.device, requires_grad=True)

    def closure() -> torch.Tensor:
        opt.zero_grad(set_to_none=True)
        T = torch.exp(log_T).clamp_min(1e-6)
        loss = F.cross_entropy(logits / T, y, reduction="mean")
        loss.backward()
        return loss

    opt = torch.optim.LBFGS([log_T], lr=0.5, max_iter=50, line_search_fn="strong_wolfe")
    opt.step(closure)

    T = float(torch.exp(log_T).detach().cpu().item())
    if not np.isfinite(T) or T <= 0:
        return 1.0
    return float(T)


def _load_xy(x_path: Path, y_path: Path) -> pd.DataFrame:
    df_x = pd.read_csv(str(x_path), encoding="utf-8")
    if y_path.exists() and y_path != x_path:
        df_y = pd.read_csv(str(y_path), encoding="utf-8")
        if "status" in df_y.columns:
            if "sample_id" in df_x.columns and "sample_id" in df_y.columns:
                df_x = df_x.merge(df_y[["sample_id", "status"]], on="sample_id", how="left")
            else:
                df_x["status"] = df_y["status"].to_numpy()
    df_x = _ensure_cols(df_x, ["status"], 0)
    df_x["status"] = pd.to_numeric(df_x["status"], errors="coerce").fillna(0).astype(np.int64)
    return df_x


def _prep_df(df: pd.DataFrame, num_cols: List[str], cat_cols: List[str]) -> pd.DataFrame:
    df = _ensure_cols(df, cat_cols, 0)
    df = _ensure_cols(df, num_cols, 0.0)
    df = _to_int(df, cat_cols)
    df = _to_num(df, num_cols)
    return df


# -----------------------
# Load checkpoint + build model (aligned)
# -----------------------
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

ckpt = torch.load(str(MODEL_PATH), map_location=device)
if not isinstance(ckpt, dict) or "model" not in ckpt or not isinstance(ckpt["model"], dict):
    raise RuntimeError("production_best.pt must be a dict checkpoint with key `model` (state_dict).")

state_dict: Dict[str, torch.Tensor] = ckpt["model"]

pv_dim = _infer_pv_dim(state_dict)
num_cols = NUM_COLS_13[:]
if len(num_cols) != pv_dim:
    if len(num_cols) > pv_dim:
        num_cols = num_cols[:pv_dim]
    else:
        for i in range(pv_dim - len(num_cols)):
            num_cols.append(f"__pad_{i}__")

cov_rows_ckpt = _infer_cov_rows_from_ckpt(state_dict, n_cat=len(COVARIATE_COLS))
num_cat_list = _num_cat_list_for_model_init(cov_rows_ckpt)

if "HybridDPNModel" not in globals():
    raise RuntimeError("HybridDPNModel is not defined. Run model-definition cells first.")
if "PseudoTargetGenerator" not in globals() or "PseudoTargetConfig" not in globals():
    raise RuntimeError("PseudoTargetGenerator / PseudoTargetConfig not defined. Run pseudo-target cells first.")

model = HybridDPNModel(
    numerical_cols=num_cols,
    categorical_cols=COVARIATE_COLS,
    num_cat_list=num_cat_list,
).to(device)
model.load_state_dict(state_dict, strict=True)
model.eval()

# -----------------------
# Load data (calib + test)
# -----------------------
if not X_TEST_PATH.exists():
    raise FileNotFoundError(f"Missing X test: {X_TEST_PATH}")

df_test = _load_xy(X_TEST_PATH, Y_TEST_PATH)

use_explicit_calib = X_CALIB_PATH.exists() and Y_CALIB_PATH.exists()
if use_explicit_calib:
    df_calib = _load_xy(X_CALIB_PATH, Y_CALIB_PATH)
else:
    n = int(len(df_test))
    idx = np.arange(n, dtype=np.int64)
    rng = np.random.default_rng(SEED)
    rng.shuffle(idx)
    n_cal = int(max(1, round(CALIB_FALLBACK_FRAC * n)))
    cal_idx = idx[:n_cal]
    tst_idx = idx[n_cal:]
    df_calib = df_test.iloc[cal_idx].reset_index(drop=True)
    df_test = df_test.iloc[tst_idx].reset_index(drop=True)

df_calib = _prep_df(df_calib, num_cols, COVARIATE_COLS)
df_test = _prep_df(df_test, num_cols, COVARIATE_COLS)

x_num_c = torch.tensor(df_calib[num_cols].to_numpy(dtype=np.float32, copy=False), dtype=torch.float32, device=device)
x_num_t = torch.tensor(df_test[num_cols].to_numpy(dtype=np.float32, copy=False), dtype=torch.float32, device=device)

x_cat_c_np = _clamp_cats_np(df_calib[COVARIATE_COLS].to_numpy(dtype=np.int64, copy=False), cov_rows_ckpt)
x_cat_t_np = _clamp_cats_np(df_test[COVARIATE_COLS].to_numpy(dtype=np.int64, copy=False), cov_rows_ckpt)

x_cat_c = torch.tensor(x_cat_c_np, dtype=torch.long, device=device)
x_cat_t = torch.tensor(x_cat_t_np, dtype=torch.long, device=device)

status_c = torch.tensor(df_calib["status"].to_numpy(dtype=np.int64, copy=False), dtype=torch.long, device=device)
status_t = torch.tensor(df_test["status"].to_numpy(dtype=np.int64, copy=False), dtype=torch.long, device=device)

# -----------------------
# Pseudo labels (axis truth)
# -----------------------
pseudo_cfg = PseudoTargetConfig()
pseudo_gen = PseudoTargetGenerator(meta_idx=model.meta_idx, emg_idx=model.emg_idx, cfg=pseudo_cfg)
if isinstance(ckpt.get("pseudo_state"), dict) and hasattr(pseudo_gen, "load_state_dict"):
    try:
        pseudo_gen.load_state_dict(ckpt["pseudo_state"])
    except Exception:
        pass

with torch.no_grad():
    pseudo_c = pseudo_gen.generate(x_num_c, status_c)
    pseudo_t = pseudo_gen.generate(x_num_t, status_t)

# -----------------------
# Forward
# -----------------------
with torch.no_grad():
    out_c = model(x_num_c, x_cat_c)
    out_t = model(x_num_t, x_cat_t)

if not isinstance(out_c, dict):
    out_c = dict(out_c._asdict()) if hasattr(out_c, "_asdict") else {"out": out_c}
if not isinstance(out_t, dict):
    out_t = dict(out_t._asdict()) if hasattr(out_t, "_asdict") else {"out": out_t}

# -----------------------
# Calibration per axis
# -----------------------
plot_artifacts: Dict[str, Any] = {}
rows: List[Dict[str, Any]] = []

for axis_key, spec in AXIS_SPECS.items():
    title = str(spec["title"])
    classes = list(spec["classes"])
    n_classes = len(classes)

    y_c_np = pseudo_c[axis_key].detach().cpu().numpy().astype(np.int64, copy=False)
    y_t_np_all = pseudo_t[axis_key].detach().cpu().numpy().astype(np.int64, copy=False)

    m_c = y_c_np >= 0
    m_t = y_t_np_all >= 0

    y_c = torch.tensor(y_c_np[m_c], dtype=torch.long, device=device)
    y_t_np = y_t_np_all[m_t]

    logits_c = _pick_logits(out_c, axis_key)[m_c]
    logits_t = _pick_logits(out_t, axis_key)[m_t]

    if logits_c.shape[-1] != n_classes:
        logits_c = logits_c[:, :n_classes] if logits_c.shape[-1] > n_classes else torch.cat(
            [logits_c, logits_c.new_zeros((logits_c.shape[0], n_classes - logits_c.shape[-1]))], dim=1
        )
    if logits_t.shape[-1] != n_classes:
        logits_t = logits_t[:, :n_classes] if logits_t.shape[-1] > n_classes else torch.cat(
            [logits_t, logits_t.new_zeros((logits_t.shape[0], n_classes - logits_t.shape[-1]))], dim=1
        )

    with torch.no_grad():
        proba_uncal = F.softmax(logits_t, dim=-1).detach().cpu().numpy().astype(np.float64, copy=False)

    T = _fit_temperature(logits_c, y_c)

    with torch.no_grad():
        proba_cal = F.softmax(logits_t / float(T), dim=-1).detach().cpu().numpy().astype(np.float64, copy=False)

    conf_u = proba_uncal.max(axis=1)
    pred_u = proba_uncal.argmax(axis=1).astype(np.int64)
    correct_u = (pred_u == y_t_np).astype(np.float64)

    conf_k = proba_cal.max(axis=1)
    pred_k = proba_cal.argmax(axis=1).astype(np.int64)
    correct_k = (pred_k == y_t_np).astype(np.float64)

    bins_u = _reliability_bins(conf_u, correct_u, n_bins=N_BINS)
    bins_k = _reliability_bins(conf_k, correct_k, n_bins=N_BINS)

    nll_u = _nll(y_t_np, proba_uncal)
    nll_k = _nll(y_t_np, proba_cal)
    brier_u = _brier_multiclass(y_t_np, proba_uncal, n_classes=n_classes)
    brier_k = _brier_multiclass(y_t_np, proba_cal, n_classes=n_classes)

    rows.append(
        {
            "axis": title,
            "support": int(y_t_np.shape[0]),
            "n_bins": int(N_BINS),
            "temperature": float(T),
            "ece_uncal": float(bins_u["ece"]),
            "mce_uncal": float(bins_u["mce"]),
            "nll_uncal": float(nll_u),
            "brier_uncal": float(brier_u),
            "ece_cal": float(bins_k["ece"]),
            "mce_cal": float(bins_k["mce"]),
            "nll_cal": float(nll_k),
            "brier_cal": float(brier_k),
        }
    )

    plot_artifacts[axis_key] = {
        "title": title,
        "classes": classes,
        "temperature": float(T),
        "uncal": bins_u,
        "cal": bins_k,
    }

    if SHOW_PLOTS:
        import matplotlib.pyplot as plt

        fig = plt.figure(figsize=(7.4, 5.4))
        ax = fig.add_subplot(1, 1, 1)
        ax.plot([0, 1], [0, 1], linestyle="--", linewidth=1, label="perfect")

        def _plot(ax_, bins: Dict[str, Any], label: str) -> None:
            x = np.asarray(bins["centers"], dtype=np.float64)
            acc = np.asarray(bins["bin_acc"], dtype=np.float64)
            cnt = np.asarray(bins["bin_count"], dtype=np.int64)
            m = cnt > 0
            ax_.plot(x[m], acc[m], marker="o", linewidth=1, label=f"{label}")

        _plot(ax, bins_u, "uncal")
        _plot(ax, bins_k, "cal")

        ax.set_xlim(0, 1)
        ax.set_ylim(0, 1)
        ax.set_xlabel("confidence (binned centers)")
        ax.set_ylabel("accuracy")
        ax.set_title(f"{title} — Reliability | ECE {bins_u['ece']:.3f}->{bins_k['ece']:.3f} | T={T:.3f}")
        ax.legend(loc="lower right")
        fig.tight_layout()

        out_png = PLOTS_OUT_DIR / f"{axis_key}_reliability.png"
        fig.savefig(str(out_png), dpi=180)
        plt.close(fig)

# -----------------------
# Summary table + save
# -----------------------
df_cal = pd.DataFrame(rows)

macro: Dict[str, Any] = {
    "axis": "Macro (mean over axes)",
    "support": int(df_cal["support"].sum()) if not df_cal.empty else 0,
    "n_bins": int(N_BINS),
    "temperature": float(df_cal["temperature"].mean()) if not df_cal.empty else float("nan"),
}
for c in ["ece_uncal", "mce_uncal", "nll_uncal", "brier_uncal", "ece_cal", "mce_cal", "nll_cal", "brier_cal"]:
    macro[c] = float(pd.to_numeric(df_cal[c], errors="coerce").mean()) if not df_cal.empty else float("nan")

df_cal = pd.concat([df_cal, pd.DataFrame([macro])], ignore_index=True)

df_cal = df_cal[
    [
        "axis",
        "support",
        "n_bins",
        "temperature",
        "ece_uncal",
        "mce_uncal",
        "nll_uncal",
        "brier_uncal",
        "ece_cal",
        "mce_cal",
        "nll_cal",
        "brier_cal",
    ]
]

display(df_cal)

df_cal.to_csv(CSV_OUT, index=False)
_atomic_write_json(
    JSON_OUT,
    {
        "paths": {
            "model": str(MODEL_PATH),
            "x_test": str(X_TEST_PATH),
            "y_test": str(Y_TEST_PATH),
            "x_calib": str(X_CALIB_PATH) if use_explicit_calib else str(X_TEST_PATH),
            "y_calib": str(Y_CALIB_PATH) if use_explicit_calib else str(Y_TEST_PATH),
        },
        "device": str(device),
        "used_explicit_calibration_split": bool(use_explicit_calib),
        "fallback_calib_frac": float(CALIB_FALLBACK_FRAC) if not use_explicit_calib else 0.0,
        "seed": int(SEED),
        "numerical_cols_used": list(num_cols),
        "categorical_cols_used": list(COVARIATE_COLS),
        "cov_emb_rows_ckpt": list(cov_rows_ckpt),
        "num_cat_list_passed": list(num_cat_list),
        "axis_specs": AXIS_SPECS,
        "summary_table": df_cal.to_dict(orient="records"),
        "reliability": plot_artifacts,
        "plots_dir": str(PLOTS_OUT_DIR),
        "pseudo_cfg": asdict(pseudo_cfg) if hasattr(pseudo_cfg, "__dataclass_fields__") else {},
    },
)

print(f"Saved: {CSV_OUT}")
print(f"Saved: {JSON_OUT}")
print(f"Plots: {PLOTS_OUT_DIR}")

"""**Threshold Analysis**"""

# STEP 14 — Threshold Analysis (Youden / F1 / Cost-based + Sens@Spec + Spec@Sens)
# FIXED: cov_emb shape mismatch by passing (rows-1) to HybridDPNModel AND clamping x_cat to ckpt-valid range.

