# -----------------------
# Helpers
# -----------------------
def _atomic_write_json(path: Path, obj: Any) -> None:
    tmp = path.with_suffix(path.suffix + ".tmp")
    with tmp.open("w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=2)
    os.replace(tmp, path)

def _ensure_cols(df: pd.DataFrame, cols: List[str], default_value: Any) -> pd.DataFrame:
    out = df.copy()
    for c in cols:
        if c not in out.columns:
            out[c] = default_value
    return out

def _to_num_df(df: pd.DataFrame, cols: List[str]) -> pd.DataFrame:
    out = df.copy()
    for c in cols:
        out[c] = pd.to_numeric(out[c], errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0).astype(np.float32)
    return out

def _to_int_df(df: pd.DataFrame, cols: List[str]) -> pd.DataFrame:
    out = df.copy()
    for c in cols:
        out[c] = pd.to_numeric(out[c], errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0).astype(np.int64)
    return out

def _infer_pv_dim(state_dict: Dict[str, torch.Tensor]) -> int:
    k = "pv_decoder.net.2.weight"
    if k in state_dict and isinstance(state_dict[k], torch.Tensor) and state_dict[k].ndim == 2:
        return int(state_dict[k].shape[0])
    # fallback: mecha_ae encoder first linear input dim
    for kk, vv in state_dict.items():
        if kk.endswith("mecha_ae.enc.net.0.weight") and isinstance(vv, torch.Tensor) and vv.ndim == 2:
            return int(vv.shape[1])
    raise RuntimeError("Cannot infer pv_dim from checkpoint (pv_decoder/mecha_ae missing).")

def _infer_cov_emb_sizes(state_dict: Dict[str, torch.Tensor], n_cat: int) -> List[int]:
    sizes: List[int] = []
    for i in range(n_cat):
        k = f"cov_emb.emb.{i}.weight"
        if k not in state_dict or not isinstance(state_dict[k], torch.Tensor) or state_dict[k].ndim != 2:
            raise RuntimeError(f"Cannot infer cov emb size: missing {k}")
        sizes.append(int(state_dict[k].shape[0]))
    return sizes

def _clip_cats_for_embedding(x_cat: np.ndarray, emb_rows: List[int]) -> np.ndarray:
    out = x_cat.astype(np.int64, copy=True)
    for j, rows in enumerate(emb_rows):
        max_val = max(rows - 2, -1)  # forward uses (x+1) indexing; valid original: -1..rows-2
        out[:, j] = np.clip(out[:, j], -1, max_val)
    return out

def _safe_load_state_dict(model: torch.nn.Module, state_dict: Dict[str, torch.Tensor]) -> Tuple[List[str], List[str]]:
    try:
        model.load_state_dict(state_dict, strict=True)
        return [], []
    except Exception as e:
        # drop only mismatched tensor shapes; load remaining
        dropped: List[str] = []
        kept: Dict[str, torch.Tensor] = {}
        model_sd = model.state_dict()
        for k, v in state_dict.items():
            if k in model_sd and isinstance(v, torch.Tensor) and isinstance(model_sd[k], torch.Tensor) and v.shape == model_sd[k].shape:
                kept[k] = v
            else:
                dropped.append(k)
        missing = [k for k in model_sd.keys() if k not in kept]
        model.load_state_dict(kept, strict=False)
        log.warning("Strict load failed (%s). Loaded compatible tensors with strict=False.", str(e).splitlines()[0])
        if dropped:
            log.warning("Dropped %d mismatched tensors (loaded remaining weights safely).", len(dropped))
            for k in dropped[:15]:
                log.warning("  - dropped: %s", k)
            if len(dropped) > 15:
                log.warning("  - ... (%d more)", len(dropped) - 15)
        if missing:
            log.warning("Missing keys (kept model init): %d", len(missing))
        return dropped, missing

def _pick_logits(out_dict: Dict[str, torch.Tensor], axis_key: str) -> torch.Tensor:
    for k in (f"{axis_key}_logits", axis_key):
        if k in out_dict and isinstance(out_dict[k], torch.Tensor):
            return out_dict[k]
    for k, v in out_dict.items():
        if isinstance(v, torch.Tensor) and axis_key.lower() in k.lower() and "logit" in k.lower():
            return v
    raise KeyError(f"Missing logits for {axis_key}. Keys: {list(out_dict.keys())}")

def _pick_reg(out_dict: Dict[str, torch.Tensor], key_candidates: List[str]) -> torch.Tensor:
    for k in key_candidates:
        if k in out_dict and isinstance(out_dict[k], torch.Tensor):
            return out_dict[k]
    for k, v in out_dict.items():
        lk = k.lower()
        if isinstance(v, torch.Tensor) and any(c in lk for c in [kc.lower() for kc in key_candidates]):
            return v
    raise KeyError(f"Missing reg output for {key_candidates}. Keys: {list(out_dict.keys())}")

def _softmax_np(logits: np.ndarray) -> np.ndarray:
    x = logits.astype(np.float64, copy=False)
    x = x - np.max(x, axis=1, keepdims=True)
    ex = np.exp(x)
    return ex / np.clip(ex.sum(axis=1, keepdims=True), 1e-12, None)

def _axis_pred_table(sample_id: np.ndarray, out: Dict[str, torch.Tensor]) -> pd.DataFrame:
    rows: Dict[str, Any] = {"sample_id": sample_id.astype(str)}
    for axis_key, spec in AXIS_SPECS.items():
        classes = list(spec["classes"])
        logits = _pick_logits(out, axis_key).detach().cpu().numpy()
        proba = _softmax_np(logits)
        pred = proba.argmax(axis=1).astype(np.int64)
        conf = proba.max(axis=1)
        # margin = top1 - top2
        top2 = np.partition(proba, -2, axis=1)[:, -2]
        margin = conf - top2
        rows[f"{axis_key}_pred_label"] = [classes[i] if 0 <= i < len(classes) else str(i) for i in pred.tolist()]
        rows[f"{axis_key}_pred_conf"] = conf.astype(np.float64)
        rows[f"{axis_key}_pred_margin"] = margin.astype(np.float64)
    nerve = _pick_reg(out, ["nerve_bio_age", "nerve_age", "pred_nerve_age"]).detach().cpu().numpy().reshape(-1)
    outcome = _pick_reg(out, ["pred_outcome", "outcome"]).detach().cpu().numpy().reshape(-1)
    rows["nerve_age_pred"] = nerve.astype(np.float64)
    rows["outcome_pred"] = outcome.astype(np.float64)
    return pd.DataFrame(rows)

def _local_feature_ranking(values: np.ndarray, feature_names: List[str], topk: int) -> List[Tuple[str, float]]:
    v = values.astype(np.float64, copy=False)
    idx = np.argsort(-np.abs(v))[: int(max(1, topk))]
    return [(feature_names[i], float(v[i])) for i in idx.tolist()]

def _group_sums(values: np.ndarray, feature_names: List[str]) -> Dict[str, float]:
    lookup = {f: float(values[i]) for i, f in enumerate(feature_names)}
    out: Dict[str, float] = {}
    for g, feats in PHYSIO_GROUPS.items():
        out[g] = float(np.sum([lookup.get(f, 0.0) for f in feats]))
    # keep stable ordering
    return {k: out[k] for k in PHYSIO_GROUPS.keys()}

def _direction(val: float) -> str:
    return "increase" if val >= 0 else "decrease"

def _make_explanation_text(
    sample_id: str,
    preds_row: Dict[str, Any],
    head_name: str,
    top_feats: List[Tuple[str, float]],
    group_sums: Dict[str, float],
) -> str:
    lines: List[str] = []
    lines.append(f"Patient: {sample_id}")
    if head_name in AXIS_SPECS:
        title = AXIS_SPECS[head_name]["title"]
        lines.append(
            f"{title}: predicted '{preds_row[f'{head_name}_pred_label']}' "
            f"with confidence={float(preds_row[f'{head_name}_pred_conf']):.3f} "
            f"(margin={float(preds_row[f'{head_name}_pred_margin']):.3f})."
        )
        conf = float(preds_row[f"{head_name}_pred_conf"])
        if conf >= 0.90:
            lines.append("Interpretation: confident prediction; verify against clinical context and electrophysiology.")
        elif conf >= 0.70:
            lines.append("Interpretation: moderate confidence; consider borderline patterns and confirm with clinical context.")
        else:
            lines.append("Interpretation: low confidence; likely boundary/ambiguous presentation; interpret cautiously.")
    elif head_name == "nerve_age":
        lines.append(f"Nerve bio-age prediction: {float(preds_row['nerve_age_pred']):.4f}")
    elif head_name == "outcome":
        lines.append(f"Outcome prediction: {float(preds_row['outcome_pred']):.4f}")

    lines.append("")
    lines.append("Top contributing signals (local attribution):")
    for f, s in top_feats:
        lines.append(f"- {f}: {_direction(s)} (score={s:+.4f})")

    lines.append("")
    lines.append("Physiological grouping (net local effect):")
    for g, s in group_sums.items():
        lines.append(f"- {g}: {s:+.4f}")

    emg_feats = [f for f, _ in top_feats if f in EMG_HINTS]
    if emg_feats:
        lines.append("")
        lines.append("Mechanism → muscle/nerve hints (from EMG features):")
        for f in emg_feats:
            lines.append(f"- {f}: {EMG_HINTS[f]}")
    return "\n".join(lines).strip() + "\n"

# -----------------------
# Load data
# -----------------------
if not X_PATH.exists():
    raise FileNotFoundError(f"Missing X file: {X_PATH}")

df_x = pd.read_csv(X_PATH, encoding="utf-8")
if Y_PATH.exists():
    try:
        df_y = pd.read_csv(Y_PATH, encoding="utf-8")
        if "status" in df_y.columns and "status" not in df_x.columns:
            if "sample_id" in df_x.columns and "sample_id" in df_y.columns:
                df_x = df_x.merge(df_y[["sample_id", "status"]], on="sample_id", how="left")
            else:
                df_x["status"] = df_y["status"].to_numpy()
    except Exception:
        pass

if "sample_id" not in df_x.columns:
    df_x["sample_id"] = np.arange(len(df_x)).astype(str)

df_x = _ensure_cols(df_x, ["status"], 0)
df_x["status"] = pd.to_numeric(df_x["status"], errors="coerce").fillna(0).astype(np.int64)
df_x = _ensure_cols(df_x, COVARIATE_COLS, 0)
df_x = _to_int_df(df_x, COVARIATE_COLS)

# -----------------------
# Load model checkpoint + build model to match checkpoint dims
# -----------------------
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
ckpt = torch.load(str(MODEL_PATH), map_location=device)
if not isinstance(ckpt, dict):
    raise RuntimeError("production_best.pt must be a dict checkpoint")
if "model" not in ckpt or not isinstance(ckpt["model"], dict):
    raise RuntimeError("production_best.pt must contain key 'model' (state_dict dict)")
state_dict: Dict[str, torch.Tensor] = ckpt["model"]

pv_dim = _infer_pv_dim(state_dict)
cov_sizes = _infer_cov_emb_sizes(state_dict, n_cat=len(COVARIATE_COLS))
num_cat_list = cov_sizes[:]  # EXACT match to checkpoint

# numerical columns aligned to pv_dim
num_cols = CANON_NUM_COLS_13[:]
df_x = _ensure_cols(df_x, num_cols, 0.0)
if len(num_cols) != pv_dim:
    if len(num_cols) > pv_dim:
        num_cols = num_cols[:pv_dim]
    else:
        for i in range(pv_dim - len(num_cols)):
            pad = f"__pad_{i}__"
            df_x[pad] = 0.0
            num_cols.append(pad)

df_x = _to_num_df(df_x, num_cols)

x_num_np = df_x[num_cols].to_numpy(dtype=np.float32, copy=False)
x_cat_np = df_x[COVARIATE_COLS].to_numpy(dtype=np.int64, copy=False)
x_cat_np = _clip_cats_for_embedding(x_cat_np, cov_sizes)

x_num = torch.tensor(x_num_np, dtype=torch.float32, device=device)
x_cat = torch.tensor(x_cat_np, dtype=torch.long, device=device)
status = torch.tensor(df_x["status"].to_numpy(dtype=np.int64, copy=False), dtype=torch.long, device=device)

if "HybridDPNModel" not in globals():
    raise RuntimeError("HybridDPNModel is not defined. Run the model-definition cells first.")

model = HybridDPNModel(
    numerical_cols=num_cols,
    categorical_cols=COVARIATE_COLS,
    num_cat_list=num_cat_list,
).to(device)

dropped_keys, missing_keys = _safe_load_state_dict(model, state_dict)
model.eval()

# -----------------------
# Forward pass
# -----------------------
with torch.no_grad():
    out = model(x_num, x_cat)

if not isinstance(out, dict):
    out = dict(out._asdict()) if hasattr(out, "_asdict") else {"out": out}

pred_df = _axis_pred_table(df_x["sample_id"].to_numpy(), out)
display(pred_df.head(10))
pred_df.to_csv(PRED_OUT, index=False)

# -----------------------
# SHAP (KernelExplainer) — explain NUM + CATS together via rounding/clamping, avoid x_cat gradient issues
# -----------------------
feature_names_all: List[str] = num_cols + COVARIATE_COLS
X_all = np.concatenate([x_num_np.astype(np.float64, copy=False), x_cat_np.astype(np.float64, copy=False)], axis=1)

# deterministic subsample indices
n_total = int(X_all.shape[0])
bg_n = int(min(SHAP_BACKGROUND_N, max(1, n_total)))
ex_n = int(min(SHAP_EXPLAIN_N, max(1, n_total)))
bg_idx = np.linspace(0, n_total - 1, bg_n, dtype=np.int64) if n_total > 1 else np.array([0], dtype=np.int64)
ex_idx = np.linspace(0, n_total - 1, ex_n, dtype=np.int64) if n_total > 1 else np.array([0], dtype=np.int64)

X_bg = X_all[bg_idx]
X_ex = X_all[ex_idx]
sample_ids_ex = df_x["sample_id"].astype(str).to_numpy()[ex_idx]

def _split_and_prepare(X_in: np.ndarray) -> Tuple[torch.Tensor, torch.Tensor]:
    X_in = np.asarray(X_in, dtype=np.float64)
    Xn = X_in[:, : len(num_cols)].astype(np.float32, copy=False)
    Xc = X_in[:, len(num_cols) :].astype(np.int64, copy=False)

    # clamp cats deterministically to checkpoint sizes
    Xc = _clip_cats_for_embedding(Xc, cov_sizes)

    tn = torch.tensor(Xn, dtype=torch.float32, device=device)
    tc = torch.tensor(Xc, dtype=torch.long, device=device)
    return tn, tc

def _model_predict_proba_axis(axis_key: str, X_in: np.ndarray) -> np.ndarray:
    tn, tc = _split_and_prepare(X_in)
    with torch.no_grad():
        o = model(tn, tc)
        if not isinstance(o, dict):
            o = dict(o._asdict()) if hasattr(o, "_asdict") else {"out": o}
        logits = _pick_logits(o, axis_key)
        proba = F.softmax(logits, dim=-1).detach().cpu().numpy().astype(np.float64, copy=False)
    return proba

def _model_predict_reg(head: str, X_in: np.ndarray) -> np.ndarray:
    tn, tc = _split_and_prepare(X_in)
    with torch.no_grad():
        o = model(tn, tc)
        if not isinstance(o, dict):
            o = dict(o._asdict()) if hasattr(o, "_asdict") else {"out": o}
        if head == "nerve_age":
            y = _pick_reg(o, ["nerve_bio_age", "nerve_age", "pred_nerve_age"]).detach().cpu().numpy().reshape(-1)
        else:
            y = _pick_reg(o, ["pred_outcome", "outcome"]).detach().cpu().numpy().reshape(-1)
    return y.astype(np.float64)

shap_ok = False
shap_values_by_head: Dict[str, Any] = {}
expected_by_head: Dict[str, Any] = {}

if USE_SHAP:
    try:
        import shap  # type: ignore

        shap_ok = True
        log.info("SHAP available: %s", getattr(shap, "__version__", "unknown"))

        # Axis heads — explain probability of predicted class per sample (stable 1D output for KernelExplainer)
        for axis_key, spec in AXIS_SPECS.items():
            classes = list(spec["classes"])
            proba_ex = _model_predict_proba_axis(axis_key, X_ex)
            pred_idx = proba_ex.argmax(axis=1).astype(np.int64)

            def _f_axis_predclass(X_in: np.ndarray) -> np.ndarray:
                p = _model_predict_proba_axis(axis_key, X_in)
                # use predicted class from CURRENT X_in (not ex_idx) for consistency within KernelExplainer calls:
                k = p.argmax(axis=1).astype(np.int64)
                outp = p[np.arange(p.shape[0]), k]
                return outp.reshape(-1)

            expl = shap.KernelExplainer(_f_axis_predclass, X_bg)
            sv = expl.shap_values(X_ex, nsamples=int(SHAP_NSAMPLES))
            # sv shape: (N, D)
            shap_values_by_head[axis_key] = np.asarray(sv, dtype=np.float64)
            expected_by_head[axis_key] = float(expl.expected_value)

        # Regression heads
        for head in ["nerve_age", "outcome"]:
            def _f_reg(X_in: np.ndarray, _head=head) -> np.ndarray:
                return _model_predict_reg(_head, X_in).reshape(-1)

            expl = shap.KernelExplainer(_f_reg, X_bg)
            sv = expl.shap_values(X_ex, nsamples=int(SHAP_NSAMPLES))
            shap_values_by_head[head] = np.asarray(sv, dtype=np.float64)
            expected_by_head[head] = float(expl.expected_value)

    except Exception as e:
        shap_ok = False
        log.warning("SHAP failed; continuing with gradient-only. (%s)", str(e).splitlines()[0])

# -----------------------
# Gradient fallback (local attribution only, numeric features)
# -----------------------
def _grad_attr_numeric(head: str, sample_i: int) -> np.ndarray:
    xi_num = x_num[sample_i : sample_i + 1].detach().clone().requires_grad_(True)
    xi_cat = x_cat[sample_i : sample_i + 1].detach()
    o = model(xi_num, xi_cat)
    if not isinstance(o, dict):
        o = dict(o._asdict()) if hasattr(o, "_asdict") else {"out": o}

    if head in AXIS_SPECS:
        logits = _pick_logits(o, head)
        # explain predicted class logit
        k = int(torch.argmax(logits, dim=-1).item())
        target = logits[:, k].sum()
    elif head == "nerve_age":
        target = _pick_reg(o, ["nerve_bio_age", "nerve_age", "pred_nerve_age"]).sum()
    else:
        target = _pick_reg(o, ["pred_outcome", "outcome"]).sum()

    model.zero_grad(set_to_none=True)
    if xi_num.grad is not None:
        xi_num.grad.zero_()
    target.backward()
    g = xi_num.grad.detach().cpu().numpy().reshape(-1).astype(np.float64, copy=False)
    x = xi_num.detach().cpu().numpy().reshape(-1).astype(np.float64, copy=False)
    return g * x  # grad * input

# -----------------------
# Build explanations (CSV/JSONL/TXT)
# -----------------------
def _get_local_values_for_sample(head: str, global_explain_idx: int, sample_i_full: int) -> np.ndarray:
    # Prefer SHAP on explained subset, else gradient on full sample
    if shap_ok and head in shap_values_by_head:
        # global_explain_idx refers to index within X_ex subset
        sv = np.asarray(shap_values_by_head[head], dtype=np.float64)
        if sv.ndim == 2 and 0 <= global_explain_idx < sv.shape[0]:
            return sv[global_explain_idx]
    # gradient-only over numeric cols; pad cats with 0 for unified feature vector
    g = _grad_attr_numeric(head, sample_i_full)
    pad = np.zeros((len(COVARIATE_COLS),), dtype=np.float64)
    return np.concatenate([g, pad], axis=0)

# Map sample_id -> row dict for predictions
pred_map = pred_df.set_index("sample_id").to_dict(orient="index")
explanations_rows: List[Dict[str, Any]] = []
texts: List[str] = []

# Explain only subset used by SHAP (or same subset even if SHAP off)
for j in range(ex_n):
    sid = str(sample_ids_ex[j])
    # locate full-row index in df_x deterministically via ex_idx
    full_i = int(ex_idx[j])
    preds_row = pred_map.get(sid, {})

    # Prepare per-head explanation texts
    per_patient_blocks: List[str] = []
    for head in ["axis1", "axis2", "axis3", "nerve_age", "outcome"]:
        vals = _get_local_values_for_sample(head, j, full_i)
        top = _local_feature_ranking(vals, feature_names_all, topk=LOCAL_TOPK)
        groups = _group_sums(vals[: len(num_cols)], num_cols)  # physiological groups over numeric only
        txt = _make_explanation_text(sid, preds_row, head if head in AXIS_SPECS else head, top, groups)
        per_patient_blocks.append(txt)

        explanations_rows.append(
            {
                "sample_id": sid,
                "head": head,
                "pred_axis1": preds_row.get("axis1_pred_label", ""),
                "pred_axis2": preds_row.get("axis2_pred_label", ""),
                "pred_axis3": preds_row.get("axis3_pred_label", ""),
                "axis1_conf": float(preds_row.get("axis1_pred_conf", np.nan)) if "axis1_pred_conf" in preds_row else np.nan,
                "axis2_conf": float(preds_row.get("axis2_pred_conf", np.nan)) if "axis2_pred_conf" in preds_row else np.nan,
                "axis3_conf": float(preds_row.get("axis3_pred_conf", np.nan)) if "axis3_pred_conf" in preds_row else np.nan,
                "nerve_age_pred": float(preds_row.get("nerve_age_pred", np.nan)) if "nerve_age_pred" in preds_row else np.nan,
                "outcome_pred": float(preds_row.get("outcome_pred", np.nan)) if "outcome_pred" in preds_row else np.nan,
                "top_features": json.dumps([{"feature": f, "score": s, "direction": _direction(s)} for f, s in top], ensure_ascii=False),
                "physio_groups": json.dumps(groups, ensure_ascii=False),
                "explanation_text": txt.strip(),
            }
        )

    full_text = "\n\n".join(per_patient_blocks).strip() + "\n"
    texts.append(full_text)

explanations_df = pd.DataFrame(explanations_rows)
display(explanations_df.head(10))

# -----------------------
# Global attribution summary (mean |SHAP| if available, else mean |grad*input| over explained subset)
# -----------------------
global_rows: List[Dict[str, Any]] = []

def _mean_abs(vals_2d: np.ndarray, names: List[str]) -> List[Tuple[str, float]]:
    m = np.mean(np.abs(vals_2d.astype(np.float64, copy=False)), axis=0)
    return [(names[i], float(m[i])) for i in range(len(names))]

if shap_ok:
    for head, sv in shap_values_by_head.items():
        sv2 = np.asarray(sv, dtype=np.float64)
        if sv2.ndim != 2 or sv2.shape[1] != len(feature_names_all):
            continue
        ranked = sorted(_mean_abs(sv2, feature_names_all), key=lambda t: -t[1])
        for f, v in ranked:
            global_rows.append({"head": head, "feature": f, "mean_abs_shap": float(v)})
else:
    # gradient-only mean abs over explained rows
    for head in ["axis1", "axis2", "axis3", "nerve_age", "outcome"]:
        vals_stack: List[np.ndarray] = []
        for j in range(ex_n):
            full_i = int(ex_idx[j])
            v = _grad_attr_numeric(head, full_i)
            pad = np.zeros((len(COVARIATE_COLS),), dtype=np.float64)
            vals_stack.append(np.concatenate([v, pad], axis=0))
        sv2 = np.stack(vals_stack, axis=0)
        ranked = sorted(_mean_abs(sv2, feature_names_all), key=lambda t: -t[1])
        for f, v in ranked:
            global_rows.append({"head": head, "feature": f, "mean_abs_shap": float(v)})

global_attr_df = pd.DataFrame(global_rows)
display(global_attr_df.groupby("head").head(10))

# -----------------------
# Save artifacts
# -----------------------
pred_df.to_csv(PRED_OUT, index=False)
explanations_df.to_csv(EXPL_CSV_OUT, index=False)

with EXPL_JSONL_OUT.open("w", encoding="utf-8") as f:
    for r in explanations_rows:
        f.write(json.dumps(r, ensure_ascii=False) + "\n")

with EXPL_TXT_OUT.open("w", encoding="utf-8") as f:
    for t in texts:
        f.write(t)
        f.write("\n" + ("-" * 80) + "\n\n")

global_attr_df.to_csv(GLOBAL_ATTR_OUT, index=False)

meta = {
    "paths": {"model": str(MODEL_PATH), "x": str(X_PATH), "y": str(Y_PATH) if Y_PATH.exists() else ""},
    "device": str(device),
    "seed": int(SEED),
    "numerical_cols_used": list(num_cols),
    "categorical_cols_used": list(COVARIATE_COLS),
    "num_cat_list_from_ckpt": list(num_cat_list),
    "pv_dim_from_ckpt": int(pv_dim),
    "safe_load": {"dropped_keys_count": int(len(dropped_keys)), "missing_keys_count": int(len(missing_keys))},
    "shap": {
        "enabled": bool(USE_SHAP),
        "ok": bool(shap_ok),
        "method": "KernelExplainer (rounded/clamped cats; avoids x_cat gradient issues)",
        "background_n": int(bg_n),
        "explain_n": int(ex_n),
        "nsamples": int(SHAP_NSAMPLES),
        "expected_values": expected_by_head,
        "feature_names": feature_names_all,
    },
    "groups": PHYSIO_GROUPS,
    "plots_dir": str(PLOTS_DIR),
}
_atomic_write_json(META_JSON_OUT, meta)

print(f"Saved: {PRED_OUT}")
print(f"Saved: {EXPL_CSV_OUT}")
print(f"Saved: {EXPL_JSONL_OUT}")
print(f"Saved: {EXPL_TXT_OUT}")
print(f"Saved: {GLOBAL_ATTR_OUT}")
print(f"Saved: {META_JSON_OUT}")

# Example explanation text (first explained patient)
if texts:
    print("\n--- Example explanation text (first explained patient) ---\n")
    print(texts[0])